{
  "openapi": "3.0.0",
  "info": {
    "title": "Identity API",
    "description": "<span class=\"tablenote\"><b>Note:</b> Not all the account related fields are returned for an authenticated user. The fields returned in the response are controlled by the scopes and are available only to select developers approved by business units.</span><br /><br />Retrieves the authenticated user's account profile information. It can be used to let users log into your app or site using eBay, which frees you from needing to store and protect user's PII (Personal Identifiable Information) data.",
    "contact": {
      "name": "eBay Inc,"
    },
    "license": {
      "name": "eBay API License Agreement",
      "url": "https://go.developer.ebay.com/api-license-agreement"
    },
    "version": "v2.0.0"
  },
  "servers": [
    {
      "url": "https://apiz.ebay.com{basePath}",
      "description": "Production",
      "variables": {
        "basePath": {
          "default": "/commerce/identity/v1"
        }
      }
    }
  ],
  "paths": {
    "/user/": {
      "get": {
        "tags": [
          "user"
        ],
        "description": "This method retrieves the account profile information for an authenticated user, which requires a <a href=\"/api-docs/static/oauth-authorization-code-grant.html\">User access token</a>. What is returned is controlled by the <a href=\"#scopes\">scopes</a>. <p>For a business account you use the default scope <code>commerce.identity.readonly</code>, which returns all the fields in the <a href=\"/api-docs/commerce/identity/resources/user/methods/getUser#response.businessAccount\">businessAccount</a> container. These are returned  because this is all public information.</p>  <p> For an individual account, the fields returned in the <a href=\"/api-docs/commerce/identity/resources/user/methods/getUser#response.individualAccount\">individualAccount</a> container are based on the scope you use. Using the default scope, only public information, such as eBay user ID, are returned. For details about what each scope returns, see the <a href=\"/api-docs/commerce/identity/overview.html\">Identity API Overview</a>.</p> <p>In the Sandbox, this API returns mock data. <b>Note: </b> You must use the correct scope or scopes for the data you want returned.</p>",
        "operationId": "getUser",
        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UserResponse"
                }
              }
            }
          },
          "404": {
            "description": "Not found"
          },
          "500": {
            "description": "Internal Server Error",
            "x-response-codes": {
              "errors": {
                "140000": {
                  "domain": "API_IDENTITY",
                  "category": "APPLICATION",
                  "description": "There was a problem with an eBay internal system or process. Contact eBay developer support for assistance."
                }
              }
            }
          }
        },
        "security": [
          {
            "api_auth": [
              "https://api.ebay.com/oauth/api_scope/commerce.identity.readonly",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.name.readonly",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.address.readonly",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.email.readonly",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.phone.readonly"
            ]
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "Address": {
        "type": "object",
        "properties": {
          "addressLine1": {
            "type": "string",
            "description": "The first line of the street address."
          },
          "addressLine2": {
            "type": "string",
            "description": "The second line of the street address. This field is not always used, but can be used for 'Suite Number' or 'Apt Number'."
          },
          "city": {
            "type": "string",
            "description": "The city of the address."
          },
          "country": {
            "type": "string",
            "description": "The two-letter <a href=\"https://www.iso.org/iso-3166-country-codes.html\">ISO 3166</a> standard of the country of the address. For implementation help, refer to <a href='https://developer.ebay.com/api-docs/commerce/identity/types/bas:CountryCodeEnum'>eBay API documentation</a>"
          },
          "county": {
            "type": "string",
            "description": "The county of the address."
          },
          "postalCode": {
            "type": "string",
            "description": "The postal code of the address."
          },
          "stateOrProvince": {
            "type": "string",
            "description": "The state or province of the address."
          }
        },
        "description": "The type that defines the fields for an address."
      },
      "BusinessAccount": {
        "type": "object",
        "properties": {
          "address": {
            "description": "The container that returns the address of the business account. ",
            "$ref": "#/components/schemas/Address"
          },
          "doingBusinessAs": {
            "type": "string",
            "description": "An additional name that is used for their business on eBay. The business name is returned in the <b> name</b> field."
          },
          "email": {
            "type": "string",
            "description": "The email address of the business account."
          },
          "name": {
            "type": "string",
            "description": "The business name associated with the user's eBay account."
          },
          "primaryContact": {
            "description": "The container that returns the contact details of the person who is the primary contact for this account.",
            "$ref": "#/components/schemas/Contact"
          },
          "primaryPhone": {
            "description": "The container that returns the primary phone number for the business account.",
            "$ref": "#/components/schemas/Phone"
          },
          "secondaryPhone": {
            "description": "The container that returns the secondary phone number for the business account.",
            "$ref": "#/components/schemas/Phone"
          },
          "website": {
            "type": "string",
            "description": "The business website address associated with the eBay account."
          }
        },
        "description": "The type that defines the fields for the business account information."
      },
      "Contact": {
        "type": "object",
        "properties": {
          "firstName": {
            "type": "string",
            "description": "The first name of the contact person."
          },
          "lastName": {
            "type": "string",
            "description": "The last name of the contact person."
          }
        },
        "description": "The type that defines the fields for the information of the contact person for the account."
      },
      "Error": {
        "type": "object",
        "properties": {
          "category": {
            "type": "string",
            "description": "Identifies the type of erro."
          },
          "domain": {
            "type": "string",
            "description": "Name for the primary system where the error occurred. This is relevant for application errors."
          },
          "errorId": {
            "type": "integer",
            "description": "A unique number to identify the error.",
            "format": "int32"
          },
          "inputRefIds": {
            "type": "array",
            "description": "An array of request elements most closely associated to the error.",
            "items": {
              "type": "string"
            }
          },
          "longMessage": {
            "type": "string",
            "description": "A more detailed explanation of the error."
          },
          "message": {
            "type": "string",
            "description": "Information on how to correct the problem, in the end user's terms and language where applicable."
          },
          "outputRefIds": {
            "type": "array",
            "description": "An array of request elements most closely associated to the error.",
            "items": {
              "type": "string"
            }
          },
          "parameters": {
            "type": "array",
            "description": "An array of name/value pairs that describe details the error condition. These are useful when multiple errors are returned.",
            "items": {
              "$ref": "#/components/schemas/ErrorParameter"
            }
          },
          "subdomain": {
            "type": "string",
            "description": "Further helps indicate which subsystem the error is coming from. System subcategories include: Initialization, Serialization, Security, Monitoring, Rate Limiting, etc."
          }
        },
        "description": "This type defines the fields that can be returned in an error."
      },
      "ErrorParameter": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The object of the error."
          },
          "value": {
            "type": "string",
            "description": "The value of the object."
          }
        }
      },
      "IndividualAccount": {
        "type": "object",
        "properties": {
          "email": {
            "type": "string",
            "description": "The eBay user's registration email address."
          },
          "firstName": {
            "type": "string",
            "description": "The eBay user's first name."
          },
          "lastName": {
            "type": "string",
            "description": "The eBay user's last name."
          },
          "primaryPhone": {
            "description": "The container that returns the eBay user's primary phone number information.",
            "$ref": "#/components/schemas/Phone"
          },
          "registrationAddress": {
            "description": "The container that returns the eBay user's address information.",
            "$ref": "#/components/schemas/Address"
          },
          "secondaryPhone": {
            "description": "The container that returns the eBay user's secondary phone number information.",
            "$ref": "#/components/schemas/Phone"
          }
        },
        "description": "The type that defines the fields for the information of an individual account."
      },
      "Phone": {
        "type": "object",
        "properties": {
          "countryCode": {
            "type": "string",
            "description": "The two-letter <a href=\"https://www.iso.org/iso-3166-country-codes.html\">ISO 3166</a> standard of the country to which the phone number belongs."
          },
          "number": {
            "type": "string",
            "description": "The numeric string representing the phone number."
          },
          "phoneType": {
            "type": "string",
            "description": "The type of phone service. <br /><br /><b> Valid Values: </b> MOBILE or LAND_LINE  <br /><br />Code so that your app gracefully handles any future changes to this list."
          }
        },
        "description": "The type that defines the fields for the details of a phone."
      },
      "UserResponse": {
        "type": "object",
        "properties": {
          "accountType": {
            "type": "string",
            "description": "Indicates the user account type. This is determined when the user registers with eBay. If they register for a business account, this value will be BUSINESS. If they register for a private account, this value will be INDIVIDUAL. This designation is required by the tax laws in the following countries:   <br /><br />EBAY_AT, EBAY_BE, EBAY_CH, EBAY_DE, EBAY_ES, EBAY_FR, EBAY_GB, EBAY_IE, EBAY_IT, EBAY_PL <br /><br /><b> Valid Values:</b> BUSINESS or INDIVIDUAL <br /><br />Code so that your app gracefully handles any future changes to this list. For implementation help, refer to <a href='https://developer.ebay.com/api-docs/commerce/identity/types/api:AccountTypeEnum'>eBay API documentation</a>"
          },
          "businessAccount": {
            "description": "The container that returns the business account information of the user.",
            "$ref": "#/components/schemas/BusinessAccount"
          },
          "individualAccount": {
            "description": "The account information of the user.",
            "$ref": "#/components/schemas/IndividualAccount"
          },
          "registrationMarketplaceId": {
            "type": "string",
            "description": "The eBay site on which the account is registered. For implementation help, refer to <a href='https://developer.ebay.com/api-docs/commerce/identity/types/bas:MarketplaceIdEnum'>eBay API documentation</a>"
          },
          "status": {
            "type": "string",
            "description": "Indicates the user's account status. Possible values: <code>CONFIRMED</code>, <code>UNCONFIRMED</code>, <code>ACCOUNTONHOLD</code> and <code>UNDETERMINED</code>. For implementation help, refer to <a href='https://developer.ebay.com/api-docs/commerce/identity/types/api:UserStatusEnum'>eBay API documentation</a>"
          },
          "userId": {
            "type": "string",
            "description": "The eBay immutable user ID of the user's account and can always be used to identify the user."
          },
          "username": {
            "type": "string",
            "description": "The user name, which was specific by the user when they created the account. <br /><br /><span class=\"tablenote\"><b>Note: </b> This value can be changed by the user.</span>"
          }
        },
        "description": "The type that defines the fields for the <b>getUser</b> method."
      }
    },
    "securitySchemes": {
      "api_auth": {
        "type": "oauth2",
        "description": "The security definitions for this API. Please check individual operations for applicable scopes.",
        "flows": {
          "authorizationCode": {
            "authorizationUrl": "https://auth.ebay.com/oauth2/authorize",
            "tokenUrl": "https://api.ebay.com/identity/v1/oauth2/token",
            "scopes": {
              "https://api.ebay.com/oauth/api_scope/commerce.identity.email.readonly": "View a user's personal email information from their eBay member account",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.address.readonly": "View a user's personal address information from their eBay member account",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.readonly": "View a user's basic information, such as username or business account details, from their eBay member account",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.name.readonly": "View a user's first and last name from their eBay member account",
              "https://api.ebay.com/oauth/api_scope/commerce.identity.phone.readonly": "View a user's personal telephone information from their eBay member account"
            }
          }
        }
      }
    }
  }
}

{
    "openapi": "3.0.0",
    "info": {
        "title": "Vero Public API's",
        "description": "The VeRO API has methods that allow owners of an intellectual property to report eBay listings that infringe on their intellectual property rights. It contains methods to report a listing, retrieve supported VeRO reason codes, and retrieve the status of reported items.",
        "contact": {
            "name": "eBay Inc,"
        },
        "license": {
            "name": "eBay API License Agreement",
            "url": "https://developer.ebay.com/join/api-license-agreement"
        },
        "version": "1.0.0"
    },
    "servers": [
        {
            "url": "https://api.ebay.com{basePath}",
            "description": "Production",
            "variables": {
                "basePath": {
                    "default": "/commerce/vero/v1"
                }
            }
        }
    ],
    "paths": {
        "/vero_reason_code/{vero_reason_code_id}": {
            "get": {
                "tags": [
                    "vero_reason_code"
                ],
                "description": "<div class=\"msgbox_important\"><p class=\"msgbox_importantInDiv\" data-mc-autonum=\"&lt;b&gt;&lt;span style=&quot;color: #dd1e31;&quot; class=&quot;mcFormatColor&quot;&gt;Important! &lt;/span&gt;&lt;/b&gt;\"><span class=\"autonumber\"><span><b><span style=\"color: #dd1e31;\" class=\"mcFormatColor\">Important!</span></b></span></span> You must be a member of the Verified Rights Owner (VeRO) Program to use this call.</p></div><br>This method is used to retrieve the details of a specific VeRO reason code, including a description of the code and the marketplace associated with the code.<br><br>The <b>vero_reason_code_id</b> of the VeRO reason code for which to retrieve details is required as a path parameter.",
                "operationId": "getVeroReasonCode",
                "parameters": [
                    {
                        "name": "vero_reason_code_id",
                        "in": "path",
                        "description": "This path parameter specifies the unique identifier of the VeRO reason code that is to be retrieved.<br><br>Use the <a href=\"/api-docs/commerce/vero/resources/vero_reason_code/methods/getVeroReasonCodes\" target=\"_blank \">getVeroReasonCodes</a> method to retrieve supported VeRO reason code IDs.",
                        "required": true,
                        "schema": {
                            "type": "string"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "OK",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/VeroReasonCodeResponse"
                                }
                            }
                        }
                    },
                    "400": {
                        "description": "Bad Request",
                        "x-response-codes": {
                            "errors": {
                                "235001": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "The veroReasonCodeId was not found."
                                }
                            }
                        }
                    },
                    "500": {
                        "description": "Internal Server Error",
                        "x-response-codes": {
                            "errors": {
                                "235000": {
                                    "domain": "API_VERO",
                                    "category": "APPLICATION",
                                    "description": "There was a problem with an eBay internal system or process."
                                }
                            }
                        }
                    }
                },
                "security": [
                    {
                        "api_auth": [
                            "https://api.ebay.com/oauth/api_scope/commerce.vero"
                        ]
                    }
                ]
            }
        },
        "/vero_reason_code": {
            "get": {
                "tags": [
                    "vero_reason_code"
                ],
                "description": "<div class=\"msgbox_important\"><p class=\"msgbox_importantInDiv\" data-mc-autonum=\"&lt;b&gt;&lt;span style=&quot;color: #dd1e31;&quot; class=&quot;mcFormatColor&quot;&gt;Important! &lt;/span&gt;&lt;/b&gt;\"><span class=\"autonumber\"><span><b><span style=\"color: #dd1e31;\" class=\"mcFormatColor\">Important!</span></b></span></span> You must be a member of the Verified Rights Owner (VeRO) Program to use this call.</p></div><br>This method is used to retrieve the details of an array of VeRO reason codes. This information includes the descriptions of each code, as well as the marketplace associated with each code.<br><br> If the <b>X-EBAY-C-MARKETPLACE-ID</b> header is present, only VeRO reason codes for that specific site will be returned. If this header is not included, all reason codes for all sites are returned.",
                "operationId": "getVeroReasonCodes",
                "parameters": [
                    {
                        "name": "X-EBAY-C-MARKETPLACE-ID",
                        "in": "header",
                        "description": "This header identifies the eBay marketplace for which to retrieve VeRO reason codes. If this header is used, only VeRO reason codes for the specified marketplace will be returned in the response.<br><br>See <a href=\"/api-docs/commerce/vero/types/br:MarketplaceIdEnum\" target=\"_blank \">MarketplaceIdEnum</a> for a list of supported values.",
                        "required": false,
                        "schema": {
                            "type": "string"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "OK",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/VeroReasonCodeDetailResponse"
                                }
                            }
                        }
                    },
                    "400": {
                        "description": "Bad Request"
                    },
                    "500": {
                        "description": "Internal Server Error",
                        "x-response-codes": {
                            "errors": {
                                "235000": {
                                    "domain": "API_VERO",
                                    "category": "APPLICATION",
                                    "description": "There was a problem with an eBay internal system or process."
                                }
                            }
                        }
                    }
                },
                "security": [
                    {
                        "api_auth": [
                            "https://api.ebay.com/oauth/api_scope/commerce.vero"
                        ]
                    }
                ]
            }
        },
        "/vero_report": {
            "post": {
                "tags": [
                    "vero_report"
                ],
                "description": "<div class=\"msgbox_important\"><p class=\"msgbox_importantInDiv\" data-mc-autonum=\"&lt;b&gt;&lt;span style=&quot;color: #dd1e31;&quot; class=&quot;mcFormatColor&quot;&gt;Important! &lt;/span&gt;&lt;/b&gt;\"><span class=\"autonumber\"><span><b><span style=\"color: #dd1e31;\" class=\"mcFormatColor\">Important!</span></b></span></span> You must be a member of the Verified Rights Owner (VeRO) Program to use this call.</p></div><br>This method can be used to create a VeRO report for a listing. VeRO reports can be used to report items that your copyright, trademark, or other intellectual property rights.<br><br>The <b>itemId</b> of the item being reported must be provided in the request, as well as the <b>veroReasonCodeId</b> of the claimed infringement.<br><br>You can report one or more items at a time using this method. A maximum of 150 items can be reported using this method.",
                "operationId": "createVeroReport",
                "parameters": [
                    {
                        "name": "Content-Type",
                        "in": "header",
                        "description": "This header indicates the format of the request body provided by the client. Its value should be set to <b>application/json</b>. <br><br>For more information, refer to <a href=\"/api-docs/static/rest-request-components.html#HTTP\" target=\"_blank \">HTTP request headers</a>.",
                        "required": true,
                        "schema": {
                            "type": "string"
                        }
                    }
                ],
                "requestBody": {
                    "content": {
                        "application/json": {
                            "schema": {
                                "$ref": "#/components/schemas/VeroReportItemsRequest"
                            }
                        }
                    },
                    "required": false
                },
                "responses": {
                    "201": {
                        "description": "Created",
                        "headers": {
                            "Location": {
                                "schema": {
                                    "type": "string",
                                    "description": "The <b>Location</b> response header returns the created report resource location."
                                }
                            }
                        },
                        "content": {
                            "application/json": {
                                "schema": {
                                    "$ref": "#/components/schemas/VeroReportItemsResponse"
                                }
                            }
                        }
                    },
                    "400": {
                        "description": "Bad Request",
                        "x-response-codes": {
                            "errors": {
                                "235012": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "Number of reported items exceeds maximum limit of 150 items."
                                },
                                "235013": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "The itemId is required for this call."
                                },
                                "235014": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "The veroReasonCodeId is required for this call."
                                },
                                "235015": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "At least one country is required for the specified reason code."
                                },
                                "235016": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "The Regions specified are not allowed"
                                },
                                "235017": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "The patent is required for this call."
                                },
                                "235019": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "Please verify brand, it should not exceed 50 characters."
                                },
                                "235020": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "The detailedMessage is required for the specified reason code."
                                },
                                "235021": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "Please verify detailedMessage, it should not exceed 1000 characters."
                                },
                                "235022": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "Please verify messageToSeller, it should not exceed 1000 characters."
                                },
                                "235023": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "Please check report, there are duplicate item reports. A duplicate report is two report on the same itemId and veroReasonCodeId combination in one packet. The same combination itemId and veroReasonCodeId can be reported in a different packet."
                                },
                                "235024": {
                                    "domain": "API_VERO_REPORT",
                                    "category": "REQUEST",
                                    "description": "At least one item is required for this call."
                                }
                            }
                        }
                    },
                    "500": {
                        "description": "Internal Server Error",
                        "x-response-codes": {
                            "errors": {
                                "235000": {
                                    "domain": "API_VERO",
                                    "category": "APPLICATION",
                                    "description": "There was a problem with an eBay internal system or process."
                                },
                                "235018": {
                                    "domain": "API_VERO",
                                    "category": "REQUEST",
                                    "description": "Please verify patent, it should not exceed 15 characters."
                                }
                            }
                        }
                    }
                },
                "security": [
                    {
                        "api_auth": [
                            "https://api.ebay.com/oauth/api_scope/commerce.vero"
                        ]
                    }
                ]
            }
        },
        "/vero_report/{vero_report_id}": {
            "get": {
                "tags": [
                    "vero_report"
                ],
                "description": "<div class=\"msgbox_important\"><p class=\"msgbox_importantInDiv\" data-mc-autonum=\"&lt;b&gt;&lt;span style=&quot;color: #dd1e31;&quot; class=&quot;mcFormatColor&quot;&gt;Important! &lt;/span&gt;&lt;/b&gt;\"><span class=\"autonumber\"><span><b><span style=\"color: #dd1e31;\" class=\"mcFormatColor\">Important!</span></b></span></span> You must be a member of the Verified Rights Owner (VeRO) Program to use this call.</p></div><br>This method can be used to retrieve status information about a VeRO report you have submitted to eBay for copyright, trademark, or other intellectual property rights infringement.<br><br>The <b>vero_report_id</b> path parameter is used to specify the eBay report for which to retrieve status information.",
                "operationId": "getVeroReport",
                "parameters": [
                    {
                        "name": "includeItemDetails",
                        "in": "query",
