import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'fs';
import { tmpdir } from 'os';
import { dirname, join } from 'path';
import { applyWrite, planWrite, renderSkillTargets } from '@/skills/index.js';
import type { SkillLayer, SkillTarget } from '@/skills/index.js';

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'ebay-skills-'));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

function ownedTarget(layer: SkillLayer = 'using'): SkillTarget {
  return {
    provider: 'claude',
    scope: 'project',
    layer,
    path: join(dir, '.claude', 'skills', `ebay-mcp-${layer}`, 'SKILL.md'),
    kind: 'owned-file',
    detected: false,
  };
}

function codexTarget(layer: SkillLayer = 'using'): SkillTarget {
  return {
    provider: 'codex',
    scope: 'project',
    layer,
    path: join(dir, 'AGENTS.md'),
    kind: 'managed-block',
    detected: false,
  };
}

/** Owned-file payloads carry the ownership marker the renderer embeds. */
const OWNED = '<!-- ebay-mcp:skill:using (generated) -->\n# Using\nbody';

describe('owned-file writes', () => {
  it('creates, then reports unchanged on a re-run', () => {
    const target = ownedTarget();

    const created = planWrite(target, OWNED);
    expect(created.action).toBe('create');
    expect(applyWrite(created).written).toBe(true);
    expect(readFileSync(target.path, 'utf-8')).toBe(OWNED);

    const rerun = planWrite(target, OWNED);
    expect(rerun.action).toBe('unchanged');
    expect(applyWrite(rerun).written).toBe(false);
  });

  it('updates a file it previously generated', () => {
    const target = ownedTarget();
    applyWrite(planWrite(target, OWNED));

    const next = `${OWNED}\nmore`;
    const plan = planWrite(target, next);
    expect(plan.action).toBe('update');
    applyWrite(plan);
    expect(readFileSync(target.path, 'utf-8')).toBe(next);
  });

  it('skips a foreign file unless forced', () => {
    const target = ownedTarget();
    mkdirSync(dirname(target.path), { recursive: true });
    writeFileSync(target.path, '# someone else wrote this\n');

    const plan = planWrite(target, OWNED);
    expect(plan.action).toBe('skip-foreign');
    expect(applyWrite(plan).written).toBe(false);
    expect(readFileSync(target.path, 'utf-8')).toBe('# someone else wrote this\n');

    const forced = applyWrite(planWrite(target, OWNED), { force: true });
    expect(forced.written).toBe(true);
    expect(readFileSync(target.path, 'utf-8')).toBe(OWNED);
  });

  it('writes nothing on a dry run', () => {
    const target = ownedTarget();
    const result = applyWrite(planWrite(target, OWNED), { dryRun: true });
    expect(result.written).toBe(false);
    expect(existsSync(target.path)).toBe(false);
  });
});

describe('managed-block writes', () => {
  it('creates AGENTS.md when absent', () => {
    const target = codexTarget();
    const plan = planWrite(target, '## eBay MCP\nx');
    expect(plan.action).toBe('create');
    applyWrite(plan);
    expect(existsSync(target.path)).toBe(true);
  });

  it('preserves user content and is idempotent', () => {
    const userText = '# AGENTS.md\n\nMy own notes.\n';
    writeFileSync(join(dir, 'AGENTS.md'), userText);
    const target = codexTarget();
    const inner = '## eBay MCP\nstuff';

    const first = planWrite(target, inner);
    expect(first.action).toBe('update');
    expect(applyWrite(first).written).toBe(true);

    const after = readFileSync(target.path, 'utf-8');
    expect(after).toContain('My own notes.');
    expect(after).toContain('ebay-mcp:skill:using:start');
    expect(after).toContain(inner);

    const rerun = planWrite(target, inner);
    expect(rerun.action).toBe('unchanged');
    expect(applyWrite(rerun).written).toBe(false);
  });

  it('keeps two layers as independent blocks in one file', () => {
    const usingTarget = codexTarget('using');
    const contributingTarget = codexTarget('contributing');
    applyWrite(planWrite(usingTarget, '## Using\nu'));
    applyWrite(planWrite(contributingTarget, '## Contributing\nc'));

    const content = readFileSync(join(dir, 'AGENTS.md'), 'utf-8');
    expect(content).toContain('ebay-mcp:skill:using:start');
    expect(content).toContain('ebay-mcp:skill:contributing:start');
    expect(content).toContain('## Using');
    expect(content).toContain('## Contributing');

    applyWrite(planWrite(usingTarget, '## Using v2\nu2'));
    const updated = readFileSync(join(dir, 'AGENTS.md'), 'utf-8');
    expect(updated).toContain('## Using v2');
    expect(updated).toContain('## Contributing');
  });

  it('keeps both layers when the wizard writes them to one AGENTS.md in a single run', () => {
    // Regression: both Codex layers resolve to one AGENTS.md. Re-planning per
    // write (the wizard's apply path) must compose them; a single up-front plan
    // pass would let the second write clobber the first.
    const rendered = renderSkillTargets({
      providers: ['codex'],
      layers: ['using', 'contributing'],
      scope: 'project',
      cwd: dir,
      home: dir,
    });

    for (const item of rendered) {
      applyWrite(planWrite(item.target, item.payload));
    }

    const content = readFileSync(join(dir, 'AGENTS.md'), 'utf-8');
    expect(content).toContain('ebay-mcp:skill:using:start');
    expect(content).toContain('ebay-mcp:skill:contributing:start');
    expect(content).toContain('## Using the eBay MCP tools');
    expect(content).toContain('## Contributing to ebay-mcp');
  });
});

/**
 * Unit tests for the `.env` (de)serialization helpers in `setupShared`.
 *
 * The regression these guard against: eBay OAuth tokens look like
 * `v^1.1#i^1#...`, and dotenv treats an unquoted `#` as the start of an inline
 * comment. An unquoted token is therefore truncated to `v^1.1` on the next
 * read, silently breaking authentication (`invalid_grant — the provided
 * authorization refresh token is invalid or was issued to another client`).
 * `quoteEnvValue` must wrap such values so `dotenv.parse` restores them whole,
 * and `loadExistingConfig` must read those quoted values back without the
 * stray quotes.
 */

import { afterEach, describe, expect, it } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import dotenv from 'dotenv';
import { loadExistingConfig, quoteEnvValue } from '@/scripts/setupShared.js';

const SAMPLE_REFRESH_TOKEN = 'v^1.1#i^1#I^3#r^1#p^3#f^0#t^Ul41Xz==';

describe('quoteEnvValue', () => {
  it('quotes a token containing # so dotenv does not treat it as a comment', () => {
    const line = `EBAY_USER_REFRESH_TOKEN=${quoteEnvValue(SAMPLE_REFRESH_TOKEN)}`;
    const parsed = dotenv.parse(line);

    expect(parsed.EBAY_USER_REFRESH_TOKEN).toBe(SAMPLE_REFRESH_TOKEN);
  });

  it('truncates at # when NOT quoted (documents the bug being prevented)', () => {
    const parsed = dotenv.parse(`EBAY_USER_REFRESH_TOKEN=${SAMPLE_REFRESH_TOKEN}`);

    expect(parsed.EBAY_USER_REFRESH_TOKEN).toBe('v^1.1');
  });

  it('leaves plain values unquoted', () => {
    expect(quoteEnvValue('sandbox')).toBe('sandbox');
    expect(quoteEnvValue('EBAY_US')).toBe('EBAY_US');
    expect(quoteEnvValue('')).toBe('');
  });

  it('quotes whitespace values and escapes quotes like dotenv-stringify', () => {
    expect(quoteEnvValue('a b')).toBe('"a b"');
    // Matches the runtime store's dotenv-stringify output exactly.
    expect(quoteEnvValue('a"b')).toBe('"a\\"b"');
  });
});

describe('loadExistingConfig', () => {
  let dir: string;

  afterEach(() => {
    if (dir) rmSync(dir, { recursive: true, force: true });
  });

  it('reads a quoted #-token back without the surrounding quotes', () => {
    dir = mkdtempSync(join(tmpdir(), 'ebay-env-'));
    writeFileSync(
      join(dir, '.env'),
      [
        `EBAY_USER_REFRESH_TOKEN=${quoteEnvValue(SAMPLE_REFRESH_TOKEN)}`,
        'EBAY_ENVIRONMENT=sandbox',
        'EBAY_CLIENT_ID=your-client-id_here',
      ].join('\n'),
    );

    const config = loadExistingConfig(dir);

    expect(config.EBAY_USER_REFRESH_TOKEN).toBe(SAMPLE_REFRESH_TOKEN);
    expect(config.EBAY_ENVIRONMENT).toBe('sandbox');
    expect(config.EBAY_CLIENT_ID).toBeUndefined();
  });

  it('returns an empty object when no .env exists', () => {
    dir = mkdtempSync(join(tmpdir(), 'ebay-env-'));
    expect(loadExistingConfig(dir)).toEqual({});
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { Request, Response, NextFunction } from 'express';
import { createBearerAuthMiddleware, requireScopes } from '@/auth/oauthMiddleware.js';
import type { TokenVerifier } from '@/auth/tokenVerifier.js';
import type { VerifiedToken } from '@/auth/oauthTypes.js';
import { Effect } from 'effect';

type AuthenticatedTestRequest = Partial<Request> & { auth?: VerifiedToken };

describe('OAuth Middleware', () => {
  describe('createBearerAuthMiddleware', () => {
    let mockVerifier: TokenVerifier;
    let mockRequest: AuthenticatedTestRequest;
    let mockResponse: Partial<Response>;
    let mockNext: NextFunction;
    let statusMock: ReturnType<typeof vi.fn>;
    let jsonMock: ReturnType<typeof vi.fn>;
    let setHeaderMock: ReturnType<typeof vi.fn>;

    beforeEach(() => {
      jsonMock = vi.fn();
      statusMock = vi.fn().mockReturnValue({ json: jsonMock });
      setHeaderMock = vi.fn();

      mockRequest = {
        headers: {},
      };

      mockResponse = {
        status: statusMock,
        json: jsonMock,
        setHeader: setHeaderMock,
      };

      mockNext = vi.fn();

      mockVerifier = {
        verifyToken: vi.fn(),
      } as unknown as TokenVerifier;
    });

    it('reject requests without authorization header', async () => {
      const middleware = createBearerAuthMiddleware({
        verifier: mockVerifier,
        resourceMetadataUrl: 'http://localhost:3000/.well-known/oauth-protected-resource',
        realm: 'test-realm',
      });

      await middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).not.toHaveBeenCalled();
      expect(statusMock).toHaveBeenCalledWith(401);
      expect(setHeaderMock).toHaveBeenCalled();
      expect(jsonMock).toHaveBeenCalledWith({
        error: 'invalid_token',
        error_description: 'No authorization header provided',
      });
    });

    it('reject invalid authorization header format', async () => {
      mockRequest.headers = {
        authorization: 'InvalidFormat token123',
      };

      const middleware = createBearerAuthMiddleware({
        verifier: mockVerifier,
        resourceMetadataUrl: 'http://localhost:3000/.well-known/oauth-protected-resource',
      });

      await middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).not.toHaveBeenCalled();
      expect(statusMock).toHaveBeenCalledWith(401);
    });

    it('reject authorization header without token', async () => {
      mockRequest.headers = {
        authorization: 'Bearer',
      };

      const middleware = createBearerAuthMiddleware({
        verifier: mockVerifier,
        resourceMetadataUrl: 'http://localhost:3000/.well-known/oauth-protected-resource',
      });

      await middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).not.toHaveBeenCalled();
      expect(statusMock).toHaveBeenCalledWith(401);
    });

    it('verify valid bearer token', async () => {
      const validToken: VerifiedToken = {
        token: 'valid-token',
        clientId: 'test-client',
        scopes: ['mcp:tools'],
        expiresAt: Date.now() / 1000 + 3600,
        audience: 'http://localhost:3000',
        subject: 'user123',
      };

      (mockVerifier.verifyToken as ReturnType<typeof vi.fn>).mockReturnValue(
        Effect.succeed(validToken),
      );

      mockRequest.headers = {
        authorization: 'Bearer valid-token',
      };

      const middleware = createBearerAuthMiddleware({
        verifier: mockVerifier,
        resourceMetadataUrl: 'http://localhost:3000/.well-known/oauth-protected-resource',
      });

      await middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockVerifier.verifyToken).toHaveBeenCalledWith('valid-token');
      expect(mockNext).toHaveBeenCalled();
      expect(mockRequest.auth).toEqual(validToken);
    });

    it('reject invalid token', async () => {
      (mockVerifier.verifyToken as ReturnType<typeof vi.fn>).mockReturnValue(
        Effect.fail(new Error('Token expired')),
      );

      mockRequest.headers = {
        authorization: 'Bearer invalid-token',
      };

      const middleware = createBearerAuthMiddleware({
        verifier: mockVerifier,
        resourceMetadataUrl: 'http://localhost:3000/.well-known/oauth-protected-resource',
      });

      await middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).not.toHaveBeenCalled();
      expect(statusMock).toHaveBeenCalledWith(401);
      expect(jsonMock).toHaveBeenCalledWith({
        error: 'invalid_token',
        error_description: 'Token expired',
      });
    });

    it('handle verifier errors gracefully', async () => {
      (mockVerifier.verifyToken as ReturnType<typeof vi.fn>).mockReturnValue(
        Effect.fail(new Error('Unexpected error')),
      );

      mockRequest.headers = {
        authorization: 'Bearer some-token',
      };

      const middleware = createBearerAuthMiddleware({
        verifier: mockVerifier,
        resourceMetadataUrl: 'http://localhost:3000/.well-known/oauth-protected-resource',
      });

      await middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(statusMock).toHaveBeenCalledWith(401);
    });
  });

  describe('requireScopes', () => {
    let mockRequest: Partial<Request>;
    let mockResponse: Partial<Response>;
    let mockNext: NextFunction;
    let statusMock: ReturnType<typeof vi.fn>;
    let jsonMock: ReturnType<typeof vi.fn>;

    beforeEach(() => {
      jsonMock = vi.fn();
      statusMock = vi.fn().mockReturnValue({ json: jsonMock });

      mockRequest = {};
      mockResponse = {
        status: statusMock,
        json: jsonMock,
      };
      mockNext = vi.fn();
    });

    it('reject requests without auth', () => {
      const middleware = requireScopes(['mcp:admin']);

      middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).not.toHaveBeenCalled();
      expect(statusMock).toHaveBeenCalledWith(401);
      expect(jsonMock).toHaveBeenCalledWith({
        error: 'unauthorized',
        error_description: 'No authentication information found',
      });
    });

    it('allow requests with required scopes', () => {
      mockRequest.auth = {
        token: 'test-token',
        clientId: 'test-client',
        scopes: ['mcp:admin', 'mcp:tools'],
        expiresAt: Date.now() / 1000 + 3600,
      };

      const middleware = requireScopes(['mcp:admin']);

      middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).toHaveBeenCalled();
      expect(statusMock).not.toHaveBeenCalled();
    });

    it('reject requests with insufficient scopes', () => {
      mockRequest.auth = {
        token: 'test-token',
        clientId: 'test-client',
        scopes: ['mcp:tools'],
        expiresAt: Date.now() / 1000 + 3600,
      };

      const middleware = requireScopes(['mcp:admin', 'mcp:superuser']);

      middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).not.toHaveBeenCalled();
      expect(statusMock).toHaveBeenCalledWith(403);
      expect(jsonMock).toHaveBeenCalledWith({
        error: 'insufficient_scope',
        error_description: 'Missing required scopes: mcp:admin, mcp:superuser',
        required_scopes: ['mcp:admin', 'mcp:superuser'],
        provided_scopes: ['mcp:tools'],
      });
    });

    it('allow requests with all required scopes', () => {
      mockRequest.auth = {
        token: 'test-token',
        clientId: 'test-client',
        scopes: ['mcp:admin', 'mcp:tools', 'mcp:read'],
        expiresAt: Date.now() / 1000 + 3600,
      };

      const middleware = requireScopes(['mcp:admin', 'mcp:tools']);

      middleware(mockRequest as Request, mockResponse as Response, mockNext);

      expect(mockNext).toHaveBeenCalled();
    });
  });
});

/**
 * Unit tests for the OAuth loopback callback server (`startCallbackServer`).
 *
 * These exercise the inbound-redirect edge cases that gate the whole MCP flow:
 * code capture, URL-decoding, eBay error redirects, CSRF `state` validation,
 * stray non-callback requests, custom paths, timeouts, and port conflicts.
 * Every server binds to port `0` so the OS assigns a free port (no CI clashes),
 * and `afterEach` closes them so no listener or timer leaks between tests.
 */

import { afterEach, describe, expect, it } from 'vitest';
import type { Server } from 'http';
import { startCallbackServer } from '@/auth/oauthHelper.js';

/** Resolve the actual TCP port a `0`-bound server was assigned. */
function portOf(server: Server): number {
  const address = server.address();
  if (address === null || typeof address === 'string') {
    throw new Error('server is not bound to a TCP port');
  }
  return address.port;
}

describe('startCallbackServer', () => {
  const openServers: Server[] = [];

  /** Track a started server so it is always closed after the test. */
  function track(server: Server): Server {
    openServers.push(server);
    return server;
  }

  afterEach(() => {
    for (const server of openServers.splice(0)) {
      server.close();
    }
  });

  it('captures the authorization code from the redirect', async () => {
    const { server, codePromise } = await startCallbackServer(0);
    track(server);
    const response = await fetch(`http://localhost:${portOf(server)}/oauth/callback?code=abc123`);

    expect(response.status).toBe(200);
    await expect(codePromise).resolves.toMatchObject({ code: 'abc123' });
  });

  it('URL-decodes the captured code', async () => {
    const { server, codePromise } = await startCallbackServer(0);
    track(server);
    const raw = 'v^1.1#i^1+abc/def';
    await fetch(
      `http://localhost:${portOf(server)}/oauth/callback?code=${encodeURIComponent(raw)}`,
    );

    await expect(codePromise).resolves.toMatchObject({ code: raw });
  });

  it('surfaces an OAuth error redirect with its description', async () => {
    const { server, codePromise } = await startCallbackServer(0);
    track(server);
    const response = await fetch(
      `http://localhost:${portOf(server)}/oauth/callback?error=access_denied&error_description=User%20declined`,
    );

    expect(response.status).toBe(400);
    await expect(codePromise).resolves.toMatchObject({
      error: 'access_denied',
      errorDescription: 'User declined',
    });
  });

  it('HTML-escapes a malicious error_description in the response page (no reflected XSS)', async () => {
    const { server } = await startCallbackServer(0);
    track(server);
    const payload = '<script>alert(1)</script>';
    const response = await fetch(
      `http://localhost:${portOf(server)}/oauth/callback?error=access_denied&error_description=${encodeURIComponent(payload)}`,
    );
    const body = await response.text();

    expect(response.status).toBe(400);
    expect(body).not.toContain(payload);
    expect(body).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
  });

  it('rejects a state mismatch as a CSRF defense', async () => {
    const { server, codePromise } = await startCallbackServer(0, 300_000, {
      expectedState: 'expected-state',
    });
    track(server);
    await fetch(`http://localhost:${portOf(server)}/oauth/callback?code=abc&state=tampered`);

    await expect(codePromise).resolves.toMatchObject({ error: 'invalid_state' });
  });

  it('accepts a matching state and echoes it back', async () => {
    const { server, codePromise } = await startCallbackServer(0, 300_000, {
      expectedState: 'good-state',
    });
    track(server);
    await fetch(`http://localhost:${portOf(server)}/oauth/callback?code=abc&state=good-state`);

    await expect(codePromise).resolves.toMatchObject({ code: 'abc', state: 'good-state' });
  });

  it('ignores non-callback paths and keeps waiting for the real redirect', async () => {
    const { server, codePromise } = await startCallbackServer(0);
    track(server);
    const port = portOf(server);

    const stray = await fetch(`http://localhost:${port}/favicon.ico`);
    expect(stray.status).toBe(404);

    await fetch(`http://localhost:${port}/oauth/callback?code=later`);
    await expect(codePromise).resolves.toMatchObject({ code: 'later' });
  });

  it('honors a custom callback path', async () => {
    const { server, codePromise } = await startCallbackServer(0, 300_000, { path: '/cb' });
    track(server);
    await fetch(`http://localhost:${portOf(server)}/cb?code=onpath`);

    await expect(codePromise).resolves.toMatchObject({ code: 'onpath' });
  });

  it('settles with a timeout when no redirect arrives', async () => {
    const { server, codePromise } = await startCallbackServer(0, 30);
    track(server);

    await expect(codePromise).resolves.toMatchObject({ error: 'timeout' });
  });

  it('rejects when the requested port is already in use', async () => {
    const { server } = await startCallbackServer(0);
    track(server);

    await expect(startCallbackServer(portOf(server))).rejects.toThrow();
  });
});

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import nock from 'nock';
import dotenv from 'dotenv';
import * as fs from 'fs';
import type * as FsModule from 'fs';
import { mkdtempSync, promises as fsPromises, rmSync } from 'fs';
import { tmpdir } from 'os';
import path from 'path';
import { EbayOAuthClient, type EbayOAuthError } from '@/auth/oauth.js';
import type { EbayConfig } from '@/types/ebay.js';
import { mockOAuthTokenEndpoint, cleanupMocks } from '@tests/helpers/mockHttp.js';
import process from 'node:process';
import { Effect } from 'effect';

vi.mock('fs', async () => {
  const actual = await vi.importActual<typeof FsModule>('fs');

  return {
    ...actual,
    writeFileSync: vi.fn(),
  };
});

const initializeOAuthClient = (client: EbayOAuthClient): Promise<void> =>
  Effect.runPromise(client.initialize());

const setUserTokens = (
  client: EbayOAuthClient,
  accessToken: string,
  refreshToken: string,
  accessTokenExpiry?: number,
  refreshTokenExpiry?: number,
): Promise<void> =>
  Effect.runPromise(
    client.setUserTokens(accessToken, refreshToken, accessTokenExpiry, refreshTokenExpiry),
  );

const getAccessToken = (client: EbayOAuthClient): Promise<string> =>
  Effect.runPromise(client.getAccessToken());

const exchangeCodeForToken = (client: EbayOAuthClient, code: string) =>
  Effect.runPromise(client.exchangeCodeForToken(code));

const refreshUserToken = (client: EbayOAuthClient): Promise<void> =>
  Effect.runPromise(client.refreshUserToken());

const expectOAuthFailure = async (
  effect: Effect.Effect<unknown, EbayOAuthError>,
  expected: {
    readonly operation: EbayOAuthError['operation'];
    readonly message: string | RegExp;
  },
): Promise<void> => {
  const error = await Effect.runPromise(Effect.flip(effect));

  expect(error._tag).toBe('EbayOAuthError');
  expect(error.operation).toBe(expected.operation);
  if (expected.message instanceof RegExp) {
    expect(error.message).toMatch(expected.message);
  } else {
    expect(error.message).toContain(expected.message);
  }
};

describe('EbayOAuthClient', () => {
  let oauthClient: EbayOAuthClient;
  let config: EbayConfig;

  beforeEach(() => {
    // Reset mocks
    vi.clearAllMocks();
    cleanupMocks();

    // Disable proxy to prevent the HTTP adapter from using it.
    delete process.env.HTTP_PROXY;
    delete process.env.HTTPS_PROXY;
    delete process.env.http_proxy;
    delete process.env.https_proxy;

    // Enable nock to intercept HTTP requests
    nock.disableNetConnect();

    // Default config
    config = {
      clientId: 'test_client_id',
      clientSecret: 'test_client_secret',
      environment: 'sandbox',
      redirectUri: 'https://localhost/callback',
    };

    oauthClient = new EbayOAuthClient(config);
  });

  afterEach(() => {
    cleanupMocks();
    nock.enableNetConnect();
  });

  describe('initialize', () => {
    it('loads user tokens from config when refreshToken is set', async () => {
      config = { ...config, refreshToken: 'test_refresh_token' };
      oauthClient = new EbayOAuthClient(config);

      // Mock the refresh token endpoint
      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'refreshed_access_token',
        token_type: 'Bearer',
        expires_in: 7200,
        refresh_token: 'test_refresh_token',
        refresh_token_expires_in: 47_304_000,
      });

      // Mock the app access token endpoint (called after user token refresh)
      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'app_access_token',
        token_type: 'Bearer',
        expires_in: 7200,
      });

      await initializeOAuthClient(oauthClient);

      expect(oauthClient.hasUserTokens()).toBe(true);
    });

    it('does not load tokens if config refreshToken is not set', async () => {
      await initializeOAuthClient(oauthClient);

      expect(oauthClient.hasUserTokens()).toBe(false);
    });

    it('handles invalid config refreshToken', async () => {
      config = { ...config, refreshToken: 'invalid_refresh_token' };
      oauthClient = new EbayOAuthClient(config);

      // Mock failed refresh
      nock('https://api.sandbox.ebay.com')
        .post('/identity/v1/oauth2/token')
        .reply(400, { error: 'invalid_grant' });

      await initializeOAuthClient(oauthClient);

      expect(oauthClient.hasUserTokens()).toBe(false);
    });
  });

  describe('hasUserTokens', () => {
    it('return true when user tokens are set via setUserTokens', async () => {
      await setUserTokens(oauthClient, 'access_token', 'refresh_token');

      expect(oauthClient.hasUserTokens()).toBe(true);
    });

    it('return false when no user tokens are set', () => {
      expect(oauthClient.hasUserTokens()).toBe(false);
    });
  });

  describe('getAccessToken', () => {
    it('return valid user access token', async () => {
      const accessToken = 'user_access_token';
      const refreshToken = 'user_refresh_token';

      // Set tokens with future expiry
      const futureExpiry = Date.now() + 7200 * 1000;
      await setUserTokens(oauthClient, accessToken, refreshToken, futureExpiry);

      const token = await getAccessToken(oauthClient);

      expect(token).toBe(accessToken);
    });

    it('refresh expired access token using valid refresh token', async () => {
      const newAccessToken = 'new_access_token';
      const refreshToken = 'user_refresh_token';

      // Set tokens with expired access token but valid refresh token
      const pastExpiry = Date.now() - 1000;
      const futureRefreshExpiry = Date.now() + 18 * 30 * 24 * 60 * 60 * 1000;
      await setUserTokens(
        oauthClient,
        'expired_token',
        refreshToken,
        pastExpiry,
        futureRefreshExpiry,
      );

      // Mock refresh token API call
      mockOAuthTokenEndpoint('sandbox', {
        access_token: newAccessToken,
        token_type: 'Bearer',
        expires_in: 7200,
        refresh_token: refreshToken,
        refresh_token_expires_in: 47_304_000,
      });

      const token = await getAccessToken(oauthClient);

      expect(token).toBe(newAccessToken);
    });

    it('returns tagged error when both access and refresh tokens are expired', async () => {
      // Set tokens with both expired
      const pastExpiry = Date.now() - 1000;
      await setUserTokens(oauthClient, 'expired_access', 'expired_refresh', pastExpiry, pastExpiry);

      await expectOAuthFailure(oauthClient.getAccessToken(), {
        operation: 'getAccessToken',
        message: 'User authorization expired',
      });
    });

    it('fallback to client credentials when no user tokens', async () => {
      const clientToken = 'client_credentials_token';
      mockOAuthTokenEndpoint('sandbox', {
        access_token: clientToken,
        token_type: 'Bearer',
        expires_in: 7200,
      });

      const token = await getAccessToken(oauthClient);

      expect(token).toBe(clientToken);
    });

    it('reuse cached client credentials token if still valid', async () => {
      const clientToken = 'client_credentials_token';
      mockOAuthTokenEndpoint('sandbox', {
        access_token: clientToken,
        token_type: 'Bearer',
        expires_in: 7200,
      });

      // First call fetches the token.
      const token1 = await getAccessToken(oauthClient);
      expect(token1).toBe(clientToken);

      // Second call uses the cached token (no new HTTP call).
      const token2 = await getAccessToken(oauthClient);
      expect(token2).toBe(clientToken);

      // Verify only one HTTP call was made
      expect(nock.pendingMocks().length).toBe(0);
    });
  });

  describe('setUserTokens', () => {
    it('store user tokens in memory', async () => {
      const accessToken = 'user_access_token';
      const refreshToken = 'user_refresh_token';

      await setUserTokens(oauthClient, accessToken, refreshToken);

      expect(oauthClient.hasUserTokens()).toBe(true);

      // Verify tokens work by getting access token
      const token = await getAccessToken(oauthClient);
      expect(token).toBe(accessToken);
    });

    it('set default expiry times when not provided', async () => {
      const accessToken = 'user_access_token';
      const refreshToken = 'user_refresh_token';

      await setUserTokens(oauthClient, accessToken, refreshToken);

      // Verify token is available (not expired)
      const token = await getAccessToken(oauthClient);
      expect(token).toBe(accessToken);
    });
  });

  describe('exchangeCodeForToken', () => {
    it('exchange authorization code for user tokens', async () => {
      const code = 'authorization_code_12345';
      const accessToken = 'exchanged_access_token';
      const refreshToken = 'exchanged_refresh_token';

      mockOAuthTokenEndpoint('sandbox', {
        access_token: accessToken,
        token_type: 'Bearer',
        expires_in: 7200,
        refresh_token: refreshToken,
        refresh_token_expires_in: 47_304_000,
        scope: 'https://api.ebay.com/oauth/api_scope/sell.inventory',
      });

      const result = await exchangeCodeForToken(oauthClient, code);

      expect(result.access_token).toBe(accessToken);
      expect(result.refresh_token).toBe(refreshToken);
      expect(oauthClient.hasUserTokens()).toBe(true);
    });

    it('returns tagged error if redirect URI is not configured', async () => {
      const configWithoutRedirect = { ...config, redirectUri: undefined };
      const clientWithoutRedirect = new EbayOAuthClient(configWithoutRedirect);

      await expectOAuthFailure(clientWithoutRedirect.exchangeCodeForToken('code_12345'), {
        operation: 'exchangeCodeForToken',
        message: 'Redirect URI is required',
      });
    });

    it('handle OAuth exchange errors', async () => {
      const code = 'invalid_code';

      nock('https://api.sandbox.ebay.com').post('/identity/v1/oauth2/token').reply(400, {
        error: 'invalid_grant',
        error_description: 'Invalid authorization code',
      });

      await expectOAuthFailure(oauthClient.exchangeCodeForToken(code), {
        operation: 'exchangeCodeForToken',
        message: 'Invalid authorization code',
      });
    });
  });

  describe('clearAllTokens', () => {
    it('clear all tokens from memory', async () => {
      // Set tokens first
      await setUserTokens(oauthClient, 'access_token', 'refresh_token');
      expect(oauthClient.hasUserTokens()).toBe(true);

      await oauthClient.clearAllTokens();

      expect(oauthClient.hasUserTokens()).toBe(false);
    });
  });

  describe('getTokenInfo', () => {
    it('return token status information when tokens are set', async () => {
      await setUserTokens(oauthClient, 'access_token', 'refresh_token');
      const info = oauthClient.getTokenInfo();

      expect(info.hasUserToken).toBe(true);
    });

    it('return info when no tokens are available', () => {
      const info = oauthClient.getTokenInfo();

      expect(info.hasUserToken).toBe(false);
      expect(info.hasAppAccessToken).toBe(false);
    });
  });

  describe('isAuthenticated', () => {
    it('return true when valid user tokens exist', async () => {
      const futureExpiry = Date.now() + 7200 * 1000;
      await setUserTokens(oauthClient, 'access_token', 'refresh_token', futureExpiry);

      expect(oauthClient.isAuthenticated()).toBe(true);
    });

    it('return false when tokens are expired', async () => {
      const pastExpiry = Date.now() - 1000;
      await setUserTokens(oauthClient, 'expired_access', 'expired_refresh', pastExpiry, pastExpiry);

      expect(oauthClient.isAuthenticated()).toBe(false);
    });

    it('return false when no tokens are available', () => {
      expect(oauthClient.isAuthenticated()).toBe(false);
    });
  });

  describe('OAuth token persistence (issues #113, #114)', () => {
    let originalCwd: string;
    let tempDir: string;

    const writeFileSyncMock = vi.mocked(fs.writeFileSync);

    /**
     * Locate the most recent fs.writeFileSync call targeting `.env`
     * and return its parsed content. Used to verify token persistence.
     */
    const getLastEnvWrite = (): {
      filePath: string;
      content: string;
      parsed: Record<string, string>;
    } => {
      const envWrite = [...writeFileSyncMock.mock.calls]
        .reverse()
        .find(([filePath]) => String(filePath).endsWith(`${path.sep}.env`));

      expect(envWrite).toBeDefined();

      const [filePath, content] = envWrite!;
      expect(String(filePath)).toMatch(/[\\/]\.env$/);
      expect(typeof content).toBe('string');

      const envContent = content as string;
      return {
        filePath: String(filePath),
        content: envContent,
        parsed: dotenv.parse(envContent),
      };
    };

    beforeEach(() => {
      originalCwd = process.cwd();
      tempDir = mkdtempSync(path.join(tmpdir(), 'ebay-oauth-persistence-'));
      process.chdir(tempDir);
      writeFileSyncMock.mockClear();
    });

    afterEach(() => {
      process.chdir(originalCwd);
      rmSync(tempDir, { recursive: true, force: true });
      writeFileSyncMock.mockClear();
    });

    it('exchangeCodeForToken persists both access and refresh tokens to .env (issue #113)', async () => {
      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'AT1',
        token_type: 'Bearer',
        expires_in: 7200,
        refresh_token: 'RT1',
        refresh_token_expires_in: 47_304_000,
      });

      await exchangeCodeForToken(oauthClient, 'auth_code');

      const envWrite = getLastEnvWrite();
      expect(envWrite.content).toContain('EBAY_USER_ACCESS_TOKEN=AT1');
      expect(envWrite.content).toContain('EBAY_USER_REFRESH_TOKEN=RT1');
    });

    it('exchangeCodeForToken does not persist when refresh_token is missing (issue #154)', async () => {
      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'AT_only',
        token_type: 'Bearer',
        expires_in: 7200,
      });

      await expectOAuthFailure(oauthClient.exchangeCodeForToken('auth_code'), {
        operation: 'exchangeCodeForToken',
        message: 'did not include a non-empty refresh_token',
      });

      const envWrite = [...writeFileSyncMock.mock.calls].find(([filePath]) =>
        String(filePath).endsWith(`${path.sep}.env`),
      );
      expect(envWrite).toBeUndefined();
    });

    it('refreshUserToken persists in-memory refresh token to .env even when eBay omits refresh_token (issue #114)', async () => {
      oauthClient = new EbayOAuthClient({ ...config, refreshToken: 'stale_env_refresh' });
      await setUserTokens(oauthClient, 'old_access_token', 'in_memory_refresh');
      writeFileSyncMock.mockClear();

      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'new_access_token',
        expires_in: 7200,
      });

      await refreshUserToken(oauthClient);

      const envWrite = getLastEnvWrite();
      expect(envWrite.parsed.EBAY_USER_ACCESS_TOKEN).toBe('new_access_token');
      expect(envWrite.parsed.EBAY_USER_REFRESH_TOKEN).toBe('in_memory_refresh');
      expect(envWrite.parsed.EBAY_USER_REFRESH_TOKEN).not.toBe('stale_env_refresh');
    });

    it('refreshUserToken persists same refresh token when in-memory differs from env (issue #114, no rotation case)', async () => {
      oauthClient = new EbayOAuthClient({ ...config, refreshToken: 'old_env_refresh' });
      await setUserTokens(oauthClient, 'old_access_token', 'fresh_oauth_refresh');
      writeFileSyncMock.mockClear();

      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'new_access_token',
        expires_in: 7200,
        refresh_token: 'fresh_oauth_refresh',
      });

      await refreshUserToken(oauthClient);

      const envWrite = getLastEnvWrite();
      expect(envWrite.parsed.EBAY_USER_ACCESS_TOKEN).toBe('new_access_token');
      expect(envWrite.parsed.EBAY_USER_REFRESH_TOKEN).toBe('fresh_oauth_refresh');
    });

    it('refreshUserToken does NOT rewrite refresh token when in-memory matches env', async () => {
      oauthClient = new EbayOAuthClient({ ...config, refreshToken: 'same_refresh' });
      await fsPromises.writeFile(
        path.join(tempDir, '.env'),
        'EBAY_USER_REFRESH_TOKEN=same_refresh\nEBAY_USER_ACCESS_TOKEN=old_access\n',
      );
      await setUserTokens(oauthClient, 'old_access_token', 'same_refresh');
      writeFileSyncMock.mockClear();

      mockOAuthTokenEndpoint('sandbox', {
        access_token: 'new_access_token',
        expires_in: 7200,
      });

      await refreshUserToken(oauthClient);

      const envWrite = getLastEnvWrite();
      expect(envWrite.parsed.EBAY_USER_ACCESS_TOKEN).toBe('new_access_token');
      expect(envWrite.parsed.EBAY_USER_REFRESH_TOKEN).toBe('same_refresh');
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import nock from 'nock';
import * as jose from 'jose';
import { Effect } from 'effect';
import { TokenVerifier, type TokenVerifierError } from '@/auth/tokenVerifier.js';
import { invalidInput } from '@tests/helpers/invalidInput.js';
import type { OAuthServerMetadata } from '@/auth/oauthTypes.js';

vi.mock('jose');

// All test endpoints live on this origin; nock intercepts native fetch.
const ORIGIN = 'http://localhost:8080';
const METADATA_PATH = '/realms/master/.well-known/openid-configuration';
const INTROSPECT_PATH = '/realms/master/protocol/openid-connect/token/introspect';

const initializeVerifier = (verifier: TokenVerifier): Promise<void> =>
  Effect.runPromise(verifier.initialize());

const verifyToken = (verifier: TokenVerifier, token: string) =>
  Effect.runPromise(verifier.verifyToken(token));

const expectVerifierFailure = async (
  effect: Effect.Effect<unknown, TokenVerifierError>,
  expected: {
    readonly operation: TokenVerifierError['operation'];
    readonly reason: TokenVerifierError['reason'];
    readonly message: string | RegExp;
  },
): Promise<void> => {
  const error = await Effect.runPromise(Effect.flip(effect));

  expect(error._tag).toBe('TokenVerifierError');
  expect(error.operation).toBe(expected.operation);
  expect(error.reason).toBe(expected.reason);
  if (expected.message instanceof RegExp) {
    expect(error.message).toMatch(expected.message);
  } else {
    expect(error.message).toContain(expected.message);
  }
};

describe('TokenVerifier', () => {
  const mockMetadata: OAuthServerMetadata = {
    issuer: 'http://localhost:8080/realms/master',
    authorization_endpoint: 'http://localhost:8080/realms/master/protocol/openid-connect/auth',
    token_endpoint: 'http://localhost:8080/realms/master/protocol/openid-connect/token',
    jwks_uri: 'http://localhost:8080/realms/master/protocol/openid-connect/certs',
    introspection_endpoint: `${ORIGIN}${INTROSPECT_PATH}`,
  };

  beforeEach(() => {
    vi.clearAllMocks();
    nock.disableNetConnect();
  });

  afterEach(() => {
    nock.cleanAll();
    nock.enableNetConnect();
    vi.restoreAllMocks();
  });

  describe('initialize', () => {
    it('load metadata from URL', async () => {
      const scope = nock(ORIGIN).get(METADATA_PATH).reply(200, mockMetadata);

      const verifier = new TokenVerifier({
        authServerMetadata: `${ORIGIN}${METADATA_PATH}`,
        expectedAudience: 'http://localhost:3000',
      });

      await initializeVerifier(verifier);

      expect(scope.isDone()).toBe(true);
    });

    it('use provided metadata object', async () => {
      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
      });

      // No HTTP call is made when metadata is supplied inline.
      await expect(initializeVerifier(verifier)).resolves.toBeUndefined();
      expect(nock.pendingMocks()).toHaveLength(0);
    });

    it('returns tagged error if metadata loading fails', async () => {
      nock(ORIGIN).get(METADATA_PATH).reply(500, { error: 'server_error' });

      const verifier = new TokenVerifier({
        authServerMetadata: `${ORIGIN}${METADATA_PATH}`,
        expectedAudience: 'http://localhost:3000',
      });

      await expectVerifierFailure(verifier.initialize(), {
        operation: 'initialize',
        reason: 'metadataRequest',
        message: /Failed to load OAuth server metadata/,
      });
    });
  });

  describe('verifyToken - introspection', () => {
    it('verify token via introspection', async () => {
      const expectedBasic = `Basic ${Buffer.from('mcp-server:secret').toString('base64')}`;
      nock(ORIGIN).get('/.well-known/openid-configuration').reply(200, mockMetadata);
      nock(ORIGIN)
        .post(INTROSPECT_PATH, (body) => {
          // nock parses urlencoded bodies into objects; credentials must not appear here
          const params =
            typeof body === 'string'
              ? Object.fromEntries(new URLSearchParams(body))
              : (body as Record<string, string>);
          expect(params.token).toBe('test-token');
          expect(params.client_id).toBeUndefined();
          expect(params.client_secret).toBeUndefined();
          return true;
        })
        .matchHeader('Authorization', expectedBasic)
        .matchHeader('Content-Type', 'application/x-www-form-urlencoded')
        .reply(200, {
          active: true,
          client_id: 'test-client',
          scope: 'mcp:tools mcp:admin',
          exp: Math.floor(Date.now() / 1000) + 3600,
          aud: 'http://localhost:3000',
          sub: 'user123',
        });

      const verifier = new TokenVerifier({
        authServerMetadata: `${ORIGIN}/.well-known/openid-configuration`,
        expectedAudience: 'http://localhost:3000',
        clientId: 'mcp-server',
        clientSecret: 'secret',
        requiredScopes: ['mcp:tools'],
        useIntrospection: true,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-token');

      expect(result).toMatchObject({
        token: 'test-token',
        clientId: 'test-client',
        scopes: ['mcp:tools', 'mcp:admin'],
        audience: 'http://localhost:3000',
        subject: 'user123',
      });
    });

    it('sends client credentials as HTTP Basic auth, not form fields', async () => {
      const clientId = 'basic-client';
      const clientSecret = 'basic-secret';
      const expectedBasic = `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString('base64')}`;
      let capturedAuth: string | undefined;
      let capturedBody: string | undefined;

      nock(ORIGIN)
        .post(INTROSPECT_PATH, (body) => {
          capturedBody = typeof body === 'string' ? body : new URLSearchParams(body).toString();
          return true;
        })
        .matchHeader('Authorization', (value) => {
          capturedAuth = value;
          return value === expectedBasic;
        })
        .reply(200, {
          active: true,
          client_id: 'test-client',
          scope: 'mcp:tools',
          aud: 'http://localhost:3000',
        });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        clientId,
        clientSecret,
        useIntrospection: true,
      });

      await initializeVerifier(verifier);
      await verifyToken(verifier, 'opaque-token');

      expect(capturedAuth).toBe(expectedBasic);
      expect(capturedBody).toContain('token=opaque-token');
      expect(capturedBody).not.toContain('client_id');
      expect(capturedBody).not.toContain('client_secret');
    });

    it('omits Authorization when client credentials are incomplete', async () => {
      nock(ORIGIN)
        .post(INTROSPECT_PATH)
        .matchHeader('Authorization', (value) => value === undefined)
        .reply(200, {
          active: true,
          client_id: 'test-client',
          scope: 'mcp:tools',
          aud: 'http://localhost:3000',
        });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        clientId: 'only-id',
        // clientSecret intentionally omitted
        useIntrospection: true,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-token');
      expect(result.token).toBe('test-token');
    });

    it('reject inactive tokens', async () => {
      nock(ORIGIN).post(INTROSPECT_PATH).reply(200, { active: false });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: true,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('invalid-token'), {
        operation: 'verifyViaIntrospection',
        reason: 'inactiveToken',
        message: 'Token is not active',
      });
    });

    it('reject tokens with invalid audience', async () => {
      nock(ORIGIN)
        .post(INTROSPECT_PATH)
        .reply(200, { active: true, aud: 'http://different-server:3000', scope: 'mcp:tools' });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: true,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('test-token'), {
        operation: 'verifyViaIntrospection',
        reason: 'invalidAudience',
        message: /Invalid audience/,
      });
    });

    it('reject tokens with missing scopes', async () => {
      nock(ORIGIN)
        .post(INTROSPECT_PATH)
        .reply(200, { active: true, aud: 'http://localhost:3000', scope: 'mcp:tools' });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        requiredScopes: ['mcp:admin', 'mcp:superuser'],
        useIntrospection: true,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('test-token'), {
        operation: 'verifyViaIntrospection',
        reason: 'missingScopes',
        message: /Missing required scopes/,
      });
    });

    it('handle introspection endpoint errors', async () => {
      nock(ORIGIN).post(INTROSPECT_PATH).reply(400, { error_description: 'Invalid token' });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: true,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('test-token'), {
        operation: 'verifyViaIntrospection',
        reason: 'introspectionRequest',
        message: 'Token introspection failed: Invalid token',
      });
    });

    it('returns tagged error if introspection endpoint is not available', async () => {
      const metadataWithoutIntrospection = {
        issuer: 'http://localhost:8080/realms/master',
        authorization_endpoint: 'http://localhost:8080/realms/master/protocol/openid-connect/auth',
        token_endpoint: 'http://localhost:8080/realms/master/protocol/openid-connect/token',
        jwks_uri: 'http://localhost:8080/realms/master/protocol/openid-connect/certs',
      };

      const verifier = new TokenVerifier({
        authServerMetadata: metadataWithoutIntrospection,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: true,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('test-token'), {
        operation: 'verifyViaIntrospection',
        reason: 'missingIntrospectionEndpoint',
        message: 'Introspection endpoint not available',
      });
    });
  });

  describe('verifyToken - JWT', () => {
    it('verify token via JWT validation', async () => {
      const mockJWKS = vi.fn();
      const mockPayload = {
        iss: mockMetadata.issuer,
        aud: 'http://localhost:3000',
        sub: 'user123',
        client_id: 'test-client',
        scope: 'mcp:tools mcp:admin',
        exp: Math.floor(Date.now() / 1000) + 3600,
      };

      vi.mocked(jose.createRemoteJWKSet).mockReturnValue(invalidInput(mockJWKS));
      vi.mocked(jose.jwtVerify).mockResolvedValue({
        payload: mockPayload,
        protectedHeader: invalidInput({}),
      });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        requiredScopes: ['mcp:tools'],
        useIntrospection: false,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-jwt-token');

      expect(result).toMatchObject({
        token: 'test-jwt-token',
        clientId: 'test-client',
        scopes: ['mcp:tools', 'mcp:admin'],
        subject: 'user123',
      });

      expect(jose.jwtVerify).toHaveBeenCalledWith('test-jwt-token', mockJWKS, {
        issuer: mockMetadata.issuer,
        audience: 'http://localhost:3000',
      });
    });

    it('handle scope as array in JWT', async () => {
      const mockJWKS = vi.fn();
      const mockPayload = {
        iss: mockMetadata.issuer,
        aud: 'http://localhost:3000',
        scope: ['mcp:tools', 'mcp:admin'],
        client_id: 'test-client',
        exp: Math.floor(Date.now() / 1000) + 3600,
      };

      vi.mocked(jose.createRemoteJWKSet).mockReturnValue(invalidInput(mockJWKS));
      vi.mocked(jose.jwtVerify).mockResolvedValue({
        payload: mockPayload,
        protectedHeader: invalidInput({}),
      });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: false,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-jwt-token');

      expect(result.scopes).toEqual(['mcp:tools', 'mcp:admin']);
    });

    it('reject JWT with missing scopes', async () => {
      const mockJWKS = vi.fn();
      const mockPayload = {
        iss: mockMetadata.issuer,
        aud: 'http://localhost:3000',
        scope: 'mcp:tools',
        client_id: 'test-client',
        exp: Math.floor(Date.now() / 1000) + 3600,
      };

      vi.mocked(jose.createRemoteJWKSet).mockReturnValue(invalidInput(mockJWKS));
      vi.mocked(jose.jwtVerify).mockResolvedValue({
        payload: mockPayload,
        protectedHeader: invalidInput({}),
      });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        requiredScopes: ['mcp:admin'],
        useIntrospection: false,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('test-jwt-token'), {
        operation: 'verifyViaJWT',
        reason: 'missingScopes',
        message: /Missing required scopes/,
      });
    });

    it('returns tagged error if JWKS URI is not available', async () => {
      const metadataWithoutJWKS = {
        issuer: 'http://localhost:8080/realms/master',
        authorization_endpoint: 'http://localhost:8080/realms/master/protocol/openid-connect/auth',
        token_endpoint: 'http://localhost:8080/realms/master/protocol/openid-connect/token',
      };

      const verifier = new TokenVerifier({
        authServerMetadata: metadataWithoutJWKS as OAuthServerMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: false,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('test-token'), {
        operation: 'verifyViaJWT',
        reason: 'missingJwksUri',
        message: 'JWKS URI not available',
      });
    });

    it('handle JWT verification failures', async () => {
      vi.mocked(jose.createRemoteJWKSet).mockReturnValue(invalidInput(vi.fn()));
      vi.mocked(jose.jwtVerify).mockRejectedValue(new Error('Invalid signature'));

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: false,
      });

      await initializeVerifier(verifier);

      await expectVerifierFailure(verifier.verifyToken('invalid-jwt'), {
        operation: 'verifyViaJWT',
        reason: 'jwtVerification',
        message: 'JWT verification failed: Invalid signature',
      });
    });

    it('use azp claim if client_id not present', async () => {
      const mockJWKS = vi.fn();
      const mockPayload = {
        iss: mockMetadata.issuer,
        aud: 'http://localhost:3000',
        azp: 'authorized-party-client',
        scope: 'mcp:tools',
        exp: Math.floor(Date.now() / 1000) + 3600,
      };

      vi.mocked(jose.createRemoteJWKSet).mockReturnValue(invalidInput(mockJWKS));
      vi.mocked(jose.jwtVerify).mockResolvedValue({
        payload: mockPayload,
        protectedHeader: invalidInput({}),
      });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: false,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-jwt-token');

      expect(result.clientId).toBe('authorized-party-client');
    });
  });

  describe('validateAudience', () => {
    it('validate audience with trailing slash normalization', async () => {
      nock(ORIGIN)
        .post(INTROSPECT_PATH)
        .reply(200, { active: true, aud: 'http://localhost:3000/', scope: 'mcp:tools' });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: true,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-token');

      expect(result).toBeDefined();
    });

    it('validate audience array', async () => {
      nock(ORIGIN)
        .post(INTROSPECT_PATH)
        .reply(200, {
          active: true,
          aud: ['http://localhost:3000', 'http://example.com'],
          scope: 'mcp:tools',
        });

      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
        useIntrospection: true,
      });

      await initializeVerifier(verifier);
      const result = await verifyToken(verifier, 'test-token');

      expect(result).toBeDefined();
    });
  });

  describe('verifyToken - not initialized', () => {
    it('returns tagged error if verify token is called before initialization', async () => {
      const verifier = new TokenVerifier({
        authServerMetadata: mockMetadata,
        expectedAudience: 'http://localhost:3000',
      });

      await expectVerifierFailure(verifier.verifyToken('test-token'), {
        operation: 'verifyToken',
        reason: 'notInitialized',
        message: 'Token verifier not initialized',
      });
    });
  });
});

